html:
{%- import "costeo_yelke/templates/print/oc_yelke.html" as oc -%}
{#- Solicitud de cotización a proveedores. Al mandarla por correo ERPNext genera un PDF
    por proveedor con doc.vendor = ese proveedor; impresa a mano, lista a todos.
    Precio e importe van en blanco para que el proveedor los llene. Diseño:
    templates/print/oc_yelke.html -#}
{%- set fechas = doc.items | map(attribute="schedule_date") | select | unique | list -%}
{%- set mensaje = (doc.message_for_supplier or "") | striptags | trim -%}
{%- if mensaje.startswith("Please supply the specified items") %}{% set mensaje = "" %}{% endif -%}
{{ oc.estilos() }}
{{ oc.membrete_encabezado(doc, no_letterhead, print_settings, "Solicitud de cotización") }}
<div class="pdf-container">
{{ oc.marca_borrador(doc) }}
{%- if doc.get("vendor") %}
{%- set tercero = {"etiqueta": "Proveedor", "nombre": frappe.db.get_value("Supplier", doc.vendor, "supplier_name") or doc.vendor, "rfc": rfc_tercero("Supplier", doc.vendor), "direccion": []} %}
{%- else %}
{%- set tercero = {"etiqueta": "Proveedores", "nombre": doc.suppliers | map(attribute="supplier") | join(" · "), "rfc": "", "direccion": []} %}
{%- endif %}
{{ oc.datos(doc, tercero,
    [("Fecha de elaboración", fecha_corta(doc.transaction_date)),
     ("Entrega requerida", fecha_corta(doc.schedule_date) if doc.schedule_date else None),
     ("Entregar en", (doc.items[0].warehouse if doc.items else None)),
     ("Renglones", doc.items | length)]) }}
<table class="items-table">
    <thead><tr>
        <th style="width:6mm">#</th><th>Artículo</th>
        {% if fechas | length > 1 %}<th style="width:24mm">Requerida</th>{% endif %}
        <th class="text-right" style="width:26mm">Cantidad</th>
        <th class="text-right" style="width:26mm">Precio unitario</th>
        <th class="text-right" style="width:28mm">Importe</th>
    </tr></thead>
    <tbody>
    {% for row in doc.items %}
        <tr>
            <td class="muted">{{ loop.index }}</td>
            <td>{{ oc.celda_articulo(row) }}</td>
            {% if fechas | length > 1 %}<td class="muted">{{ fecha_corta(row.schedule_date) }}</td>{% endif %}
            <td class="num">{{ cantidad_uom(row.qty, row.uom or row.stock_uom) }}</td>
            <td class="num"><span class="yk-llenar"></span></td>
            <td class="num"><span class="yk-llenar"></span></td>
        </tr>
    {% endfor %}
    </tbody>
</table>
<div class="yk-notas">
    <span class="yk-lbl">Para cotizar</span>
    <div class="terms-content">
        {% if mensaje %}{{ doc.message_for_supplier }}{% else %}Favor de cotizar los artículos indicados con su mejor precio, tiempo de entrega y condiciones de pago. Indique si el precio incluye flete hasta el almacén de entrega.{% endif %}
    </div>
</div>
{{ oc.cierre(doc, mostrar_pagos=false, mostrar_totales=false) }}
</div>
{{ oc.membrete_pie(doc, no_letterhead, print_settings) }}
